namespace Aurora {
public static partial class TweakCatalog {
    static void RemainingRegistry(List<Tweak> list){
        string[] services={"CscService","DiagTrack","MapsBroker","StorSvc","SharedAccess"};string[] names={"Arquivos Offline","Experiências e Telemetria","Mapas baixados","Serviço de Armazenamento","Compartilhamento de Conexão"};int[] modes={4,4,3,3,4};
        for(int i=0;i<services.Length;i++){string name=services[i];list.Add(new Tweak{Id="service-"+name,Category="performance",Pt=(modes[i]==4?"Desativar ":"Definir como manual: ")+names[i],En=(modes[i]==4?"Disable ":"Set manual: ")+name,DescriptionPt="Altera o tipo de inicialização do serviço para o próximo boot, sem encerrá-lo à força. Pode afetar mapas offline, compartilhamento, sincronização ou manutenção. O estado anterior é salvo; reinicie para aplicar.",DescriptionEn="Changes the service's startup type for the next boot without forcibly stopping it. May affect offline maps, sharing, sync or maintenance. Previous state is backed up; restart to apply.",Hive="HKLM",Path=@"SYSTEM\CurrentControlSet\Services\"+name,Name="Start",Value=modes[i],MinBuild=10240,Source="Chris Titus / WinUtil"});}
        long memory=(long)(new Microsoft.VisualBasic.Devices.ComputerInfo().TotalPhysicalMemory/1024)+1024;
        list.Add(new Tweak{Id="svchost-grouping",Category="performance",Pt="Agrupar serviços em menos processos svchost (avançado)",En="Group services into fewer svchost processes (advanced)",DescriptionPt="Ajusta o limite de separação acima da RAM física. Pode reduzir o número de processos, mas diminui o isolamento de serviços e pode afetar Xbox e diagnósticos. Reinicie após aplicar ou restaurar.",DescriptionEn="Sets the splitting threshold above physical RAM. May reduce process count but reduces service isolation and can affect Xbox and diagnostics. Restart after applying or restoring.",Hive="HKLM",Path=@"SYSTEM\CurrentControlSet\Control",Name="SvcHostSplitThresholdInKB",Value=(int)Math.Min(Int32.MaxValue,memory),MinBuild=15063,Source="Chris Titus / WinUtil"});
        list.Add(new Tweak{Id="teredo-off",Category="network",Pt="Desativar túnel Teredo (avançado)",En="Disable Teredo tunnel (advanced)",DescriptionPt="Desativa Teredo pelo bit 0x08 de DisabledComponents. Pode afetar jogos e conectividade Xbox. Exige reinicialização e conflita com as outras escolhas de DisabledComponents.",DescriptionEn="Disables Teredo with DisabledComponents bit 0x08. May affect games and Xbox connectivity. Restart is required; conflicts with other DisabledComponents choices.",Hive="HKLM",Path=@"SYSTEM\CurrentControlSet\Services\Tcpip6\Parameters",Name="DisabledComponents",Value=8,MinBuild=7600});
    }
}
public static class TweakActions {
    static void NoLinks(string path){string current=Path.GetFullPath(path);while(!String.IsNullOrEmpty(current)){if((File.Exists(current)||Directory.Exists(current))&&(File.GetAttributes(current)&FileAttributes.ReparsePoint)!=0)throw new IOException("Permission tweaks cannot follow links or junctions");current=Path.GetDirectoryName(current);}}
    public static string PermissionTarget(string id){string program64=Environment.GetEnvironmentVariable("ProgramW6432")??Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles);switch(id){case "razer":return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Installer","Razer");case "logitech":return Path.Combine(program64,"LogiDownloadAssistant");case "store-search":return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Packages","Microsoft.WindowsStore_8wekyb3d8bbwe","LocalState","store.db");default:throw new ArgumentException("Unknown permission tweak");}}
    public static string BlockInstaller(string id,string backupRoot){string path=PermissionTarget(id);NoLinks(path);bool file=id=="store-search",created=false;if(file&&!File.Exists(path))return "ERROR • "+L.T("O cache da Store ainda não existe. Abra a Store e tente novamente.","Store cache does not exist yet. Open Store and try again.");if(!file&&!Directory.Exists(path)){Directory.CreateDirectory(path);created=true;}NoLinks(path);
        Directory.CreateDirectory(backupRoot);string backup=Path.Combine(backupRoot,"TweakPermission-"+Guid.NewGuid().ToString("N")+".xml");
        FileSystemSecurity security=file?(FileSystemSecurity)File.GetAccessControl(path,AccessControlSections.Access):Directory.GetAccessControl(path,AccessControlSections.Access);string previous=security.GetSecurityDescriptorSddlForm(AccessControlSections.Access);var sid=new SecurityIdentifier(WellKnownSidType.WorldSid,null);var rights=FileSystemRights.Write|FileSystemRights.Delete;
        var record=new XElement("tweak-permission",new XAttribute("id",id),new XAttribute("path",path),new XAttribute("file",file),new XAttribute("created",created),new XAttribute("state","prepared"),new XElement("previous",previous));AtomicFiles.SaveXml(record,backup);
        var rule=new FileSystemAccessRule(sid,rights,file?InheritanceFlags.None:InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Deny);if(file){var value=(FileSecurity)security;value.AddAccessRule(rule);File.SetAccessControl(path,value);}else{var value=(DirectorySecurity)security;value.AddAccessRule(rule);Directory.SetAccessControl(path,value);}
        record.Add(new XElement("applied",security.GetSecurityDescriptorSddlForm(AccessControlSections.Access)));record.SetAttributeValue("state","applied");AtomicFiles.SaveXml(record,backup);return "OK • "+L.T("Gravação bloqueada sem apagar arquivos existentes: ","Writes blocked without deleting existing files: ")+path;
    }
    public static string RestorePermissions(string root){int count=0;var errors=new List<string>();foreach(string file in Directory.GetFiles(root,"TweakPermission-*.xml").OrderByDescending(x=>x)){try{var record=XElement.Load(file);if(record.Name!="tweak-permission"||(string)record.Attribute("state")=="undone")continue;string id=(string)record.Attribute("id"),path=(string)record.Attribute("path");if(!String.Equals(PermissionTarget(id),path,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Permission target changed");NoLinks(path);bool isFile=(bool)record.Attribute("file");FileSystemSecurity security=isFile?(FileSystemSecurity)File.GetAccessControl(path,AccessControlSections.Access):Directory.GetAccessControl(path,AccessControlSections.Access);string actual=security.GetSecurityDescriptorSddlForm(AccessControlSections.Access);if(record.Element("applied")!=null&&actual!=record.Element("applied").Value)throw new IOException("Permissions changed after tweak; review the backup before restoring");security.SetSecurityDescriptorSddlForm(record.Element("previous").Value,AccessControlSections.Access);if(isFile)File.SetAccessControl(path,(FileSecurity)security);else Directory.SetAccessControl(path,(DirectorySecurity)security);record.SetAttributeValue("state","undone");AtomicFiles.SaveXml(record,file);count++;}catch(Exception ex){errors.Add("ERROR • "+ex.Message);}}return count+L.T(" permissão(ões) restaurada(s)."," permission change(s) restored.")+(errors.Count>0?"\n"+String.Join("\n",errors):"");}
    public static string ComponentScript(string action){switch(action){
        case "widgets":return "$packages=Get-AppxPackage | Where-Object {$_.Name -in @('MicrosoftWindows.Client.WebExperience','Microsoft.WidgetsPlatformRuntime')};if(!$packages){Write-Output 'No matching Widgets package';exit 0};foreach($p in $packages){Remove-AppxPackage -Package $p.PackageFullName -ErrorAction Stop;Write-Output ('Removed '+$p.Name)}";
        case "ai-apps":return "$packages=Get-AppxPackage | Where-Object {$_.Name -eq 'Microsoft.Copilot' -or $_.Name -eq 'Microsoft.Windows.Ai.Copilot.Provider'};foreach($p in $packages){Remove-AppxPackage -Package $p.PackageFullName -ErrorAction Stop;Write-Output ('Removed '+$p.Name)};$feature=Get-WindowsOptionalFeature -Online -FeatureName Recall -ErrorAction SilentlyContinue;if($feature -and $feature.State -eq 'Enabled'){Disable-WindowsOptionalFeature -Online -FeatureName Recall -NoRestart -ErrorAction Stop | Out-String};Write-Output 'Completed; restart if requested'";
        case "edge":return "$roots=@(${env:ProgramFiles(x86)},$env:ProgramFiles) | Where-Object {$_};$installers=@(foreach($root in $roots){Get-ChildItem -Path (Join-Path $root 'Microsoft\\Edge\\Application\\*\\Installer\\setup.exe') -ErrorAction SilentlyContinue});$setup=$installers | Sort-Object FullName -Descending | Select-Object -First 1;if(!$setup){throw 'Edge installer not found'};$s=Get-AuthenticodeSignature -LiteralPath $setup.FullName;if($s.Status -ne 'Valid' -or $s.SignerCertificate.Subject -notmatch 'Microsoft'){throw 'Edge installer signature is not valid'};$p=Start-Process -FilePath $setup.FullName -ArgumentList '--uninstall --system-level --force-uninstall' -WindowStyle Hidden -Wait -PassThru;if($p.ExitCode -ne 0){throw ('Edge removal rejected: '+$p.ExitCode)};Write-Output 'Uninstaller completed; user profile was not deleted by OuO. Windows may retain or reinstall Edge.'";
        default:throw new ArgumentException("Unknown component action");}}
}
public partial class MainWindow {
    void RemainingTweakActions(){
        var card=Card(T("Componentes e instalação automática","Components and automatic installation"),T("Ações adicionais dos catálogos de referência. Remoções usam as ferramentas do fabricante e podem exigir reinstalação posterior. Bloqueios de gravação têm backup e entram em Restaurar todos; arquivos existentes são preservados.","Additional actions from reference catalogs. Removals use vendor tooling and may need later reinstallation. Write blocks are backed up and included in Restore all; existing files are preserved."));
        var choice=new ComboBox{Margin=new System.Windows.Thickness(0,0,0,8)};string[] ids={"razer","logitech","store-search","widgets","ai-apps","edge","adobe","ultimate"};string[] labels={T("Bloquear gravação do instalador automático Razer","Block Razer automatic installer writes"),T("Bloquear gravação do Logitech Download Assistant","Block Logitech Download Assistant writes"),T("Bloquear sugestões de busca da Store pelo cache (avançado)","Block Store search suggestions through cache (advanced)"),T("Remover Widgets do usuário atual","Remove current-user Widgets"),T("Remover apps Copilot e desativar Recall disponível","Remove Copilot apps and disable available Recall"),T("Solicitar desinstalação do Edge mantendo perfil","Request Edge uninstall while preserving profile"),T("Bloquear domínios de telemetria Adobe","Block Adobe telemetry domains"),T("Adicionar plano Desempenho Máximo","Add Ultimate Performance plan")};foreach(string label in labels)choice.Items.Add(label);choice.SelectedIndex=0;card.Children.Add(choice);
        var explanation=Text("",12,Muted);card.Children.Add(explanation);Action describe=()=>{int i=choice.SelectedIndex;explanation.Text=i==2?T("Pode impedir a Store de atualizar o cache até restaurar as permissões. Não bloqueia a instalação de aplicativos por política.","May prevent Store cache updates until permissions are restored. Does not set an app installation policy."):i==5?T("A remoção pode ser recusada pelo Windows. WebView2 e perfis pessoais são preservados.","Windows may reject removal. WebView2 and personal profiles are preserved."):i==6?T("Bloqueia somente geo2.adobe.com, cc-api-data.adobe.io e cc-api-data.adobe.io.global.fastly.net. Pode afetar métricas e funções online; a lista fica em Navegação segura para revisar e remover.","Blocks only geo2.adobe.com, cc-api-data.adobe.io and cc-api-data.adobe.io.global.fastly.net. May affect metrics and online features; review/remove the list under Safe browsing."):i==7?T("Pode elevar consumo e temperatura. O plano só fica disponível quando suportado pelo Windows. Ative e restaure em Memória e desempenho.","May increase energy use and temperature. Availability depends on Windows. Activate/restore under Memory and performance."):T("Aplicação explícita com registro no histórico. O bloqueio Razer/Logitech não encerra nem remove programas já instalados.","Explicit action recorded in history. Razer/Logitech blocking does not stop or remove installed software.");};choice.SelectionChanged+=(s,e)=>describe();describe();
        var report=Input("");report.IsReadOnly=true;report.AcceptsReturn=true;report.Height=130;AttachResult(card,report);
        Row(card,Button(T("Executar ação escolhida","Run selected action"),()=>{int i=choice.SelectedIndex;if(i<0||!RequireAdmin()||!Confirm(labels[i]+"?\n\n"+explanation.Text))return;string id=ids[i];Work(T("Aplicar ação de tweaks","Apply tweak action"),()=>{if(i<3)return TweakActions.BlockInstaller(id,journal.Folder);if(i<6)return Describe(Runner.PS(TweakActions.ComponentScript(id),600000));if(id=="adobe")return HostsBlock.Apply(HostsBlock.Current().Concat(new[]{"geo2.adobe.com","cc-api-data.adobe.io","cc-api-data.adobe.io.global.fastly.net"}),journal.Folder);return Describe(Runner.Run("powercfg.exe","/duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61",30000));},r=>report.Text=r);}));
    }
}
